    let first=run(Some(&root),"run",&["--mode","loop","--no-preview"],&[("RUN_STEP3_PLAN_REVIEW_LOOP_SH",&round)]); assert!(first.status.success(),"{}",err(&first)); let expected="LOOP_STATUS=complete\nTALLY_PLAN_REVIEW_STATUS=ok\nACCEPTED_COUNT=1\nDEGRADED_PANEL=0\nNEXT_ACTION=gate-b\nSTEP3_REVIEW_LOOP_STATUS=per-round-approval-required\nROUNDS_COMPLETED=1\nFINAL_ROUND_NUM=1\nACCEPTED_COUNT=1\nDEGRADED_PANEL=0\nPLAN_REVIEW_CONTINUE_REASON=\nREASON=\n"; assert_eq!(out(&first),expected); assert_eq!(text(root.join(".step3-round-1.phase")),"awaiting-apply\n");
