#[test]
fn native_pruned_round_records_transcript_stage_argv_and_artifacts() {
    let sandbox=TempDir::new().expect("sandbox"); let root=design(&sandbox).canonicalize().expect("canonical design"); fs::write(root.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); fs::write(root.join("run-params.json"),"{}\n").expect("params"); fs::write(root.join("difficulty-rating.json"),"{\"applied_tier\":\"MODERATE\",\"panel_tier\":\"MODERATE\",\"audit_evaluated\":true,\"audit_upgrade\":null,\"escalations\":[]}\n").expect("difficulty");
    let plugin=sandbox.path().join("plugin"); fs::create_dir_all(plugin.join("scripts")).expect("scripts"); fs::create_dir_all(plugin.join("python")).expect("python"); let launcher=plugin.join("scripts/larch.sh"); script(&launcher,"root=\"${DESIGN_TMPDIR:?}\"\n[[ \"${1:-}\" == timing ]] || printf '%s\\n' \"$*\" >>\"$root/native-stage-argv.log\"\ncase \"${1:-} ${2:-}\" in\n  'plan-review panel-dispatch') printf '%s\\n' 'PANEL_PRUNED_EMPTY=true' ;;\n  'plan-review continuation') printf '%s\\n' 'PLAN_REVIEW_CONTINUE=false' 'PLAN_REVIEW_CONTINUE_REASON=converged-pruned-empty' ;;\nesac"); fs::write(plugin.join("python/cli.py"),"import sys\nif sys.argv[1:3] != ['difficulty', 'resolve-panel']:\n    raise SystemExit(2)\nprint('STATUS=ok')\nprint('PANEL_TIER=MODERATE')\nprint('ESCALATED_ROUND=false')\n").expect("python fixture");
    let native=run(Some(&root),"run",&["--mode","loop","--no-preview"],&[("CLAUDE_PLUGIN_ROOT",&plugin),("DESIGN_TMPDIR",&root)]); assert!(native.status.success(),"{}",err(&native));
    let tally=root.join("voting-tally.md"); let expected=format!("PANEL_PRUNED_EMPTY=true\nTALLY_PLAN_REVIEW_STATUS=ok\nAGGREGATOR_STATUS=skipped-pruned-empty\nACCEPTED_COUNT=0\nDEGRADED_PANEL=0\nVOTING_TALLY_FILE={}\nLOOP_STATUS=zero-findings-degraded-panel\nNEXT_ACTION=step3b\nLOOP_STATUS=zero-findings-degraded-panel\nROUNDS_COMPLETED=1\nREVIEW_ROUND_COUNT=1\nPANEL_PRUNED_EMPTY=true\nTALLY_PLAN_REVIEW_STATUS=ok\nACCEPTED_COUNT=0\nDEGRADED_PANEL=0\n",tally.display()); assert_eq!(out(&native),expected);
    let expected_argv=format!("plan-review panel-dispatch --design-tmpdir {} --round-num 1 --prune-round-num 1 --plan-file {}/plan.txt --feature-file {}/feature-description.txt --codex-present false --cursor-present false --timeout 1860 --tier MODERATE --escalated-round false\nprogress write-design-round-meta --round-dir {}/plan-review/round-1\nplan-review continuation --design-tmpdir {} --approve-requested false\n",root.display(),root.display(),root.display(),root.display(),root.display()); assert_eq!(text(root.join("native-stage-argv.log")),expected_argv);
    assert_eq!(text(root.join("plan-review/round-1/round-summary.env")),"LOOP_STATUS=zero-findings-degraded-panel\nCOLLECT_OK_COUNT=0\nCOLLECT_FAILURE_COUNT=0\nTALLY_PLAN_REVIEW_STATUS=ok\nAGGREGATOR_STATUS=skipped-pruned-empty\nACCEPTED_COUNT=0\nDEGRADED_PANEL=0\n"); assert_eq!(text(root.join("plan-review/round-1/reviewer-status.tsv")),"slot\tstatus\telapsed\n"); assert_eq!(text(root.join(".step3-review-result.env")),"NEXT_ACTION=step3b\nLOOP_STATUS=zero-findings-degraded-panel\nROUNDS_COMPLETED=1\nREVIEW_ROUND_COUNT=1\nPANEL_PRUNED_EMPTY=true\nTALLY_PLAN_REVIEW_STATUS=ok\nACCEPTED_COUNT=0\nDEGRADED_PANEL=0\nDEGRADED_PANEL_WARNING=\nINVALID_SLOT_PANEL_WARNING=\nREASON=\n"); assert!(root.join(".completed/step-3").is_file()); assert!(root.join(".completed/step-3.5").is_file());
}

#[cfg(unix)]
#[test]
fn loop_status_materialization_replaces_dangling_links_and_preserves_override_bytes() {
    let sandbox=TempDir::new().expect("sandbox"); let root=design(&sandbox); fs::write(root.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); fs::write(root.join("run-params.json"),"{\"approve_requested\":true}\n").expect("params"); let round_dir=root.join("plan-review/round-1"); fs::create_dir_all(&round_dir).expect("round");
    let output=round_dir.join("cursor-plan-arch-output.txt"); fs::write(root.join("plan-review-slots.ndjson"),format!("{{\"slot\":\"cursor-plan-arch\",\"tool\":\"cursor\",\"output\":\"{}\",\"prompt_file\":\"{}\"}}\n",output.display(),root.join("cursor.prompt").display())).expect("manifest"); symlink("/nonexistent/reviewer-status.tsv",round_dir.join("reviewer-status.tsv")).expect("status link"); fs::write(root.join(".step3-report-panel-failed.recorded"),"").expect("evidence sentinel");
    let terminal=sandbox.path().join("terminal.sh"); script(&terminal,"printf '%s\\n' 'LOOP_STATUS=panel-failed' 'TALLY_PLAN_REVIEW_STATUS=panel-failed' 'AGGREGATOR_STATUS=skipped' 'DEGRADED_PANEL=1'; exit 1"); let failed=run(Some(&root),"run",&["--mode","loop","--no-preview"],&[("RUN_STEP3_PLAN_REVIEW_LOOP_SH",&terminal)]); assert!(failed.status.success(),"{}",err(&failed)); let status=round_dir.join("reviewer-status.tsv"); assert!(!status.is_symlink()); assert_eq!(text(&status),"slot\tstatus\telapsed\nCursor-Arch\tskipped\t\n"); assert_eq!(text(root.join("latest-reviewer-status.tsv")),text(&status)); assert_eq!(text(root.join("reviewer-status-table.txt")),"📊 Reviewers: | Cursor-Arch: ⊘ |\n");

    let sandbox2=TempDir::new().expect("second sandbox"); let root2=design(&sandbox2); fs::write(root2.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); fs::write(root2.join("run-params.json"),"{\"approve_requested\":true}\n").expect("params"); let target=root2.join("old-table.txt"); fs::write(&target,"old\n").expect("target"); symlink(&target,root2.join("reviewer-status-table.txt")).expect("stable link"); let authored=sandbox.path().join("authored.sh"); script(&authored,"mkdir -p \"$DESIGN_TMPDIR/plan-review/round-1\"\nprintf 'slot\\tstatus\\telapsed\\nCodex-Arch\\tfailed\\t2m\\n' >\"$DESIGN_TMPDIR/plan-review/round-1/reviewer-status.tsv\"\nprintf '%s\\n' 'LOOP_STATUS=complete' 'TALLY_PLAN_REVIEW_STATUS=ok' 'AGGREGATOR_STATUS=ok' 'ACCEPTED_COUNT=1' 'DEGRADED_PANEL=0'"); let complete=run(Some(&root2),"run",&["--mode","loop","--no-preview"],&[("RUN_STEP3_PLAN_REVIEW_LOOP_SH",&authored)]); assert!(complete.status.success(),"{}",err(&complete)); assert_eq!(text(root2.join("latest-reviewer-status.tsv")),"slot\tstatus\telapsed\nCodex-Arch\tfailed\t2m\n"); assert!(!root2.join("reviewer-status-table.txt").is_symlink()); assert_eq!(text(root2.join("reviewer-status-table.txt")),"📊 Reviewers: | Codex-Arch: ❌ 2m |\n");
}

