#[test]
fn normalize_and_session_entry_contracts_are_exact() {
    let sandbox=TempDir::new().expect("sandbox"); let root=design(&sandbox); fs::create_dir(root.join("bgjob")).expect("bgjob"); fs::write(root.join("bgjob/design-step3-review.result.env"),"BGJOB_RC=0\nNEXT_ACTION=step3b\nSTEP3_REVIEW_LOOP_STATUS=complete\nLOOP_STATUS=complete\nROUNDS_COMPLETED=2\nFINAL_ROUND_NUM=2\nACCEPTED_COUNT=0\nDEGRADED_PANEL_WARNING='one warning'\n").expect("result");
    let read=run(Some(&root),"normalize-status",&["--read-result-env"],&[]); assert!(read.status.success()); assert_eq!(out(&read),"READ_RESULT_ENV_STATUS=ok\nBGJOB_RC=0\nNEXT_ACTION=step3b\nSTEP3_REVIEW_LOOP_STATUS=complete\nLOOP_STATUS=complete\nROUNDS_COMPLETED=2\nFINAL_ROUND_NUM=2\nACCEPTED_COUNT=0\nDEGRADED_PANEL_WARNING=one warning\nINVALID_SLOT_PANEL_WARNING=\nREASON=\n");
    fs::write(root.join("plan.txt"),"# Plan\n").expect("plan"); let source=root.join("source-env.sh"); fs::write(&source,format!("export DESIGN_TMPDIR='{}'\nexport CLAUDE_PLUGIN_ROOT='{}'\nexport ISSUE_NUMBER='8449'\n",root.display(),repo().display())).expect("session");
    let source_arg=source.to_str().expect("path"); let entry=run(None,"step3-entry-preview",&["--session-env-path",source_arg,"--claude-pid","8449"],&[]); assert!(entry.status.success(),"{}",err(&entry)); assert_eq!(out(&entry),"## Plan Candidate for Review\n\n# Plan\n\n"); let again=run(None,"step3-entry-preview",&["--session-env-path",source_arg,"--claude-pid","8449"],&[]); assert!(again.status.success()); assert!(out(&again).is_empty());

    let sandbox2=TempDir::new().expect("second sandbox"); let cwd=sandbox2.path(); fs::write(cwd.join(".pause-requested"),"").expect("pause sentinel"); let missing=Command::new(env!("CARGO_BIN_EXE_larch")).args(["plan-review","step3-entry-preview"]).current_dir(cwd).env("CLAUDE_PLUGIN_ROOT",repo()).env("LARCH_BINARY",env!("CARGO_BIN_EXE_larch")).env_remove("DESIGN_TMPDIR").env_remove("ISSUE_NUMBER").output().expect("missing preview"); assert!(missing.status.success()); assert_eq!(out(&missing),"**⚠ 3: DESIGN_TMPDIR missing or invalid; cannot present plan candidate for review**\n\n"); assert!(err(&missing).is_empty());

    let recovery_root=design(&sandbox2); let stdout_file=recovery_root.join("loop.stdout"); fs::write(&stdout_file,"WARN=stdout warning\nLOOP_STATUS=complete\nTALLY_PLAN_REVIEW_STATUS=ok\nROUNDS_COMPLETED=1\nFINAL_ROUND_NUM=1\nACCEPTED_COUNT=0\n").expect("stdout recovery"); let recovered=run(Some(&recovery_root),"normalize-status",&["--stdout-file",stdout_file.to_str().expect("stdout path"),"--loop-rc","0"],&[]); assert!(recovered.status.success(),"{}",err(&recovered)); assert_eq!(out(&recovered),"WARN=stdout warning\nNEXT_ACTION=step3b\nSTEP3_REVIEW_LOOP_STATUS=complete\nLOOP_STATUS=complete\nFINAL_ROUND_NUM=1\nTALLY_PLAN_REVIEW_STATUS=ok\nROUNDS_COMPLETED=1\nACCEPTED_COUNT=0\n"); assert_eq!(err(&recovered),"**⚠ Step 3: could not read step3 review result env; recovering from plan-review stdout when possible**\n"); assert!(!out(&recovered).contains("BGJOB_RC="));
}

#[cfg(unix)]
#[test]
fn result_envelopes_and_completion_markers_fail_closed() {
    let sandbox=TempDir::new().expect("sandbox"); let root=design(&sandbox);
    let missing=run(Some(&root),"run",&["--read-result-env"],&[]); assert_eq!(missing.status.code(),Some(1)); assert!(err(&missing).contains("result env is not a regular file"));
    fs::create_dir(root.join(".step3-review-result.env")).expect("invalid result env"); let directory=run(Some(&root),"run",&["--read-result-env"],&[]); assert_eq!(directory.status.code(),Some(1));
    fs::remove_dir(root.join(".step3-review-result.env")).expect("remove result dir"); symlink(root.join("missing-result"),root.join(".step3-review-result.env")).expect("result symlink"); let link=run(Some(&root),"run",&["--read-result-env"],&[]); assert_eq!(link.status.code(),Some(1)); fs::remove_file(root.join(".step3-review-result.env")).expect("remove link");
    fs::write(root.join(".step3-review-result.env"),b"NEXT_ACTION=first\r\nLOOP_STATUS=bad\r\nNEXT_ACTION=second\nLOOP_STATUS=complete\nNEXT_ACTION=third\nSECRET=drop\n").expect("strict result"); let strict=run(Some(&root),"run",&["--read-result-env"],&[]); assert!(strict.status.success(),"{}",err(&strict)); assert_eq!(out(&strict),"NEXT_ACTION=second\nNEXT_ACTION=third\nLOOP_STATUS=complete\n"); fs::remove_file(root.join(".step3-review-result.env")).expect("remove strict result");

    fs::write(root.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); fs::create_dir_all(root.join(".completed/step-3")).expect("invalid marker"); let terminal=sandbox.path().join("terminal.sh"); script(&terminal,"printf '%s\\n' 'LOOP_STATUS=panel-failed' 'TALLY_PLAN_REVIEW_STATUS=panel-failed' 'AGGREGATOR_STATUS=skipped' 'DEGRADED_PANEL=1'"); let marker=run(Some(&root),"run",&["--mode","loop","--no-preview"],&[("RUN_STEP3_PLAN_REVIEW_LOOP_SH",&terminal)]); assert_eq!(marker.status.code(),Some(1)); assert!(err(&marker).contains("refusing invalid completion marker"));

    let sandbox3=TempDir::new().expect("third sandbox"); let root3=design(&sandbox3); fs::write(root3.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); let outside=sandbox3.path().join("outside"); fs::create_dir(&outside).expect("outside"); symlink(&outside,root3.join(".completed")).expect("completion parent link"); let escaped=run(Some(&root3),"run",&["--mode","loop","--no-preview"],&[("RUN_STEP3_PLAN_REVIEW_LOOP_SH",&terminal)]); assert_eq!(escaped.status.code(),Some(1)); assert!(err(&escaped).contains("refusing invalid completion directory")); assert!(!outside.join("step-3").exists());

    let sandbox2=TempDir::new().expect("second sandbox"); let root2=design(&sandbox2); fs::write(root2.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); fs::write(root2.join("run-params.json"),"{\"approve_requested\":true}\n").expect("params"); fs::create_dir(root2.join(".step3-review-result.env")).expect("invalid envelope"); let round=sandbox2.path().join("round.sh"); script(&round,"printf '%s\\n' 'LOOP_STATUS=complete' 'TALLY_PLAN_REVIEW_STATUS=ok' 'AGGREGATOR_STATUS=ok' 'ACCEPTED_COUNT=1' 'DEGRADED_PANEL=0'\nprintf '%s\\n' '### FINDING_1: Required' '- **Severity**: major' '- **Concern**: Primary path fails.' >\"$DESIGN_TMPDIR/accepted-plan-findings.md\""); let envelope=run(Some(&root2),"run",&["--mode","loop","--no-preview"],&[("RUN_STEP3_PLAN_REVIEW_LOOP_SH",&round)]); assert_eq!(envelope.status.code(),Some(1)); assert!(err(&envelope).contains("plan-review run:"));
}

#[test]
fn continuation_seeds_canonical_difficulty_sources() {
    let accepted="### FINDING_1: First\n- **Severity**: major\n- **Concern**: First required path fails.\n\n### FINDING_2: Second\n- **Severity**: major\n- **Concern**: Second required path fails.\n";
    let sandbox=TempDir::new().expect("sandbox"); let raw_root=design(&sandbox); fs::write(raw_root.join("review-round-count.txt"),"1\n").expect("count"); fs::write(raw_root.join(".step3-review-result.env"),"LOOP_STATUS=complete\nTALLY_PLAN_REVIEW_STATUS=ok\nDEGRADED_PANEL=0\n").expect("result"); fs::write(raw_root.join("accepted-plan-findings.md"),accepted).expect("findings"); fs::write(raw_root.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); fs::write(raw_root.join("design-difficulty-rating.raw.json"),"{\"predicted_tier\":\"HARD\",\"confidence\":\"high\",\"rationale\":\"raw design rating\"}\n").expect("raw rating"); let raw=run(Some(&raw_root),"continuation",&["--approve-requested","false"],&[]); assert!(raw.status.success(),"{}",err(&raw)); assert!(out(&raw).contains("PANEL_TIER=HARD\n")); let raw_record:serde_json::Value=serde_json::from_str(&text(raw_root.join("difficulty-rating.json"))).expect("raw record"); assert_eq!(raw_record["design_tier"],"HARD"); assert_eq!(raw_record["rationale"],"raw design rating");

    let sandbox2=TempDir::new().expect("second sandbox"); let plan_root=design(&sandbox2); fs::write(plan_root.join("review-round-count.txt"),"1\n").expect("count"); fs::write(plan_root.join(".step3-review-result.env"),"LOOP_STATUS=complete\nTALLY_PLAN_REVIEW_STATUS=ok\nDEGRADED_PANEL=0\n").expect("result"); fs::write(plan_root.join("accepted-plan-findings.md"),accepted).expect("findings"); fs::write(plan_root.join("plan.txt"),"# Plan\n\ndifficulty: MODERATE\ndiff_lines: 1\n").expect("plan"); let planned=run(Some(&plan_root),"continuation",&["--approve-requested","false"],&[]); assert!(planned.status.success(),"{}",err(&planned)); let plan_record:serde_json::Value=serde_json::from_str(&text(plan_root.join("difficulty-rating.json"))).expect("plan record"); assert_eq!(plan_record["design_tier"],"MODERATE"); assert_eq!(plan_record["rationale"],"design plan metadata"); assert!(!plan_root.join(".plan-review-difficulty-seed.json").exists());

    let sandbox3=TempDir::new().expect("third sandbox"); let clean_root=design(&sandbox3); fs::write(clean_root.join("review-round-count.txt"),"1\n").expect("count"); fs::write(clean_root.join(".step3-review-result.env"),"LOOP_STATUS=complete\nTALLY_PLAN_REVIEW_STATUS=ok\nDEGRADED_PANEL=0\n").expect("result"); fs::write(clean_root.join("plan.txt"),"# Plan\n\ndifficulty: TRIVIAL\ndiff_lines: 1\n").expect("plan"); let clean=run(Some(&clean_root),"continuation",&["--approve-requested","false"],&[]); assert!(clean.status.success(),"{}",err(&clean)); assert!(out(&clean).contains("PLAN_REVIEW_CONTINUE_REASON=small-clean\n")); let clean_record:serde_json::Value=serde_json::from_str(&text(clean_root.join("difficulty-rating.json"))).expect("clean record"); assert_eq!(clean_record["design_tier"],"TRIVIAL"); assert!(clean_record["audit_evaluated"].is_boolean());
}

#[cfg(unix)]
#[test]
fn continuation_fails_when_hard_escalation_cannot_be_persisted() {
    let sandbox=TempDir::new().expect("sandbox"); let root=design(&sandbox); fs::write(root.join("review-round-count.txt"),"1\n").expect("count"); fs::write(root.join(".step3-review-result.env"),"LOOP_STATUS=complete\nTALLY_PLAN_REVIEW_STATUS=ok\nDEGRADED_PANEL=0\n").expect("result"); fs::write(root.join("accepted-plan-findings.md"),"### FINDING_1: First\n- **Severity**: major\n- **Concern**: First required path fails.\n\n### FINDING_2: Second\n- **Severity**: major\n- **Concern**: Second required path fails.\n").expect("findings"); fs::write(root.join("plan.txt"),"# Plan\n\ndiff_lines: 1\n").expect("plan"); let record="{\"schema_version\":3,\"predicted_tier\":\"MODERATE\",\"applied_tier\":\"MODERATE\",\"panel_tier\":\"MODERATE\",\"round_cap\":2,\"codex_model_role\":\"review\",\"audit_evaluated\":true,\"audit_upgrade\":null,\"override_source\":\"none\",\"escalations\":[]}\n"; fs::write(root.join("difficulty-rating.json"),record).expect("difficulty"); let mut locked=fs::metadata(&root).expect("metadata").permissions(); locked.set_mode(0o555); fs::set_permissions(&root,locked).expect("lock root"); let failed=run(Some(&root),"continuation",&["--approve-requested","false"],&[]); let mut restored=fs::metadata(&root).expect("locked metadata").permissions(); restored.set_mode(0o700); fs::set_permissions(&root,restored).expect("restore root"); assert_eq!(failed.status.code(),Some(1)); assert!(out(&failed).is_empty()); assert!(!err(&failed).is_empty()); assert_eq!(text(root.join("difficulty-rating.json")),record);
}
